solution:
fn withdraw(balance: &mut Int, amount: Int)
  requires: amount > 0;
  requires: balance >= amount;
{
  balance = balance - amount;
}

fn main() -> Int {
  var balance = 100;
  withdraw(&mut balance, 30);
  return balance;
}
